import {createRouter, createWebHistory} from 'vue-router'

const Example = () => import('@/views/Example.vue')
const Index = () => import('@/views/Index.vue')
const Login = () => import('@/views/Login.vue')

const Register = () => import('@/views/Register.vue')

const Analysis = () => import('@/views/Analysis.vue')
const VirtualSimulation = () => import('@/views/VirtualSimulation.vue')

const KnowledgeGraph = () => import('@/views/KnowledgeGraph.vue')
const GenerateKnowledgeGraph = () => import('@/views/GenerateKnowledgeGraph.vue')
const VideoAnalysis = () => import('@/views/VideoAnalysis.vue')
const WorkStation = () => import('@/views/WorkStation.vue')
const CsMooc = () => import('@/views/CsMooc.vue')
const CsDetail = () => import('@/views/CsDetail.vue')
const CameraAnalysis = () => import('@/views/CameraAnalysis.vue')
const DeepTutor = () => import('@/views/DeepTutor.vue')
const SmartClassroom = () => import('@/views/SmartClassroom.vue')
const SmartClassroom3D = () => import('@/views/smartclassroom/SmartClassroom3D.vue')
const LearningMonitor = () => import('@/views/smartclassroom/LearningMonitor.vue')
const ExamMonitor = () => import('@/views/smartclassroom/ExamMonitor.vue')

const NotFound = () => import('@/views/NotFound.vue')
const routes = [{
    path: '/', redirect: '/login'
},

    {
        path: '/index.html', redirect: '/login'
    },

    {
        path: '/login', name: 'Login', component: Login,
    }, {
        path: '/register', name: 'Register', component: Register,
    }, {
        path: '/videoanalysis', name: 'VideoAnalysis', component: VideoAnalysis, meta: { requireTeacher: true },
    }, {
        path: '/virtualsimulation', name: 'VirtualSimulation', component: VirtualSimulation,
    }, {
        path: '/generateknowledgegraph', name: 'GenerateKnowledgeGraph', component: GenerateKnowledgeGraph,
    }, {
        path: '/analysis', name: 'Analysis', component: Analysis,
    }, {
        path: '/workstation', name: 'WorkStation', component: WorkStation, meta: { requireTeacher: true },
    }, {
        path: '/cameraanalysis', name: 'CameraAnalysis', component: CameraAnalysis, meta: { requireTeacher: true },
    }, {
        path: '/deeptutor', name: 'DeepTutor', component: DeepTutor,
    }, {
        path: '/knowledgegraph', name: 'KnowledgeGraph', component: KnowledgeGraph,
    }, {
        path: '/index', name: 'Index', component: Index,
    }, {
        path: '/example', name: 'Example', component: Example,
    }, {
        path: '/index', name: 'Index', component: Index,
    }, {
        path: '/smart-classroom', name: 'SmartClassroom', component: SmartClassroom, meta: { requireTeacher: true },
    }, {
        path: '/smart-classroom/3d', name: 'SmartClassroom3D', component: SmartClassroom3D,
    }, {
        path: '/smart-classroom/learning-monitor', name: 'LearningMonitor', component: LearningMonitor, meta: { requireTeacher: true },
    }, {
        path: '/smart-classroom/exam-monitor', name: 'ExamMonitor', component: ExamMonitor, meta: { requireTeacher: true },
    }, {
        path: '/csmooc', name: 'CsMooc', component: CsMooc,
    }, {
        path: '/csdetail', name: 'CsDetail', component: CsDetail, children: [{
            path: '/notice', name: 'Notice', component: () => import("@/components/Notice.vue")
        }, {
            path: '/video', name: 'Video', component: () => import("@/components/Video.vue")
        }, {
            path: '/test', name: 'Test', component: () => import("@/components/Test.vue")
        }, {
            path: '/fintest', name: 'FinTest', component: () => import("@/components/FinTest.vue")
        }, {
            path: '/discusion', name: 'Discusion', component: () => import("@/components/Discusion.vue")
        }]
    }, //
    {
        path: "/:pathMatch(.*)*", name: 'notfound', component: NotFound
    }]

const router = createRouter({
    history: createWebHistory(process.env.BASE_URL), routes,
})

// 全局前置守卫：登录分流 + 学生账户拦截课堂行为分析相关页面
const TEACHER_ONLY_ROUTES = ['/workstation', '/videoanalysis', '/cameraanalysis', '/smart-classroom', '/smart-classroom/learning-monitor', '/smart-classroom/exam-monitor']

router.beforeEach((to, from, next) => {
    const username = localStorage.getItem('username')
    const role = localStorage.getItem('role') || 'student'

    // 未登录只允许访问登录/注册页
    if (!username && to.path !== '/login' && to.path !== '/register') {
        return next('/login')
    }

    // 学生账户拦截课堂行为分析相关路由，自动分流到 DeepTutor
    if (role !== 'teacher' && TEACHER_ONLY_ROUTES.includes(to.path)) {
        return next('/deeptutor')
    }

    next()
})

export default router
